'use strict';
const $=id=>document.getElementById(id),MAX=9_000_000_000_000,DB='inventory-hybrid-v1';
const en=s=>String(s??'').replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c));
const norm=s=>en(s).replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[\u200c\u200e\u200f\u061c]/g,' ').replace(/\s+/g,' ').trim().toLowerCase(),ident=s=>en(s).replace(/[\u200c\u200e\u200f\u061c\s]/g,'');
