let preparedCancel=null;
let db,deviceId,profile=null,conns={},remote=null,scopes=[],current=null,products=[],raw=null,round=1,busy=false,syncing=false,selected=null,staged=null,toastTimer,searchFrame,entryLimit=30;
const index=new InventoryIndex(norm,ident),nativeJobs=new Map(),httpJobs=new Map();
let worker=null,workerPromise=null,workerURL=null,workerJob=0;const workerJobs=new Map();
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,7000);}
const guard=fn=>async(...args)=>{try{await fn(...args);}catch(e){toast(e.message||String(e));}};
function modal(title,body){$('modalTitle').textContent=title;$('modalBody').innerHTML=body;if(!$('modal').open)$('modal').showModal();}
function closeModal(){if(preparedCancel){preparedCancel();return;}if(busy)return;$('modal').close();selected=null;if(staged){staged=null;stopWorker();}}
function qty(v){const s=en(v).replace(/٫/g,'.').replace(/٬/g,'').trim();if(!/^\d+(?:\.\d{1,3})?$/.test(s))throw Error('تعداد باید صفر یا بیشتر، با حداکثر سه رقم اعشار باشد.');const[a,b='']=s.split('.'),n=Number(a)*1000+Number(b.padEnd(3,'0'));if(!Number.isSafeInteger(n)||n>MAX)throw Error('تعداد بیش از حد مجاز است.');return n;}
function dbOpen(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>{const d=r.result;d.createObjectStore('meta',{keyPath:'key'});d.createObjectStore('scopes',{keyPath:'id'});d.createObjectStore('catalogs',{keyPath:'scopeId'});d.createObjectStore('raw',{keyPath:'scopeId'});const e=d.createObjectStore('entries',{keyPath:'id'});e.createIndex('scopeId','scopeId');e.createIndex('scopeProductRound',['scopeId','productId','round']);e.createIndex('pending','pending');};r.onsuccess=()=>{r.result.onversionchange=()=>r.result.close();resolve(r.result);};r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('نسخهٔ دیگری از برنامه باز است.'));});}
function read(store,key,by){return new Promise((resolve,reject)=>{const tx=db.transaction(store),s=tx.objectStore(store),r=by?s.index(by).getAll(key):key===undefined?s.getAll():s.get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function write(stores,queue){return new Promise((resolve,reject)=>{let tx,result,problem;try{try{tx=db.transaction(stores,'readwrite',{durability:'strict'});}catch{tx=db.transaction(stores,'readwrite');}queue(tx,x=>result=x,e=>{problem=e;tx.abort();});tx.oncomplete=()=>resolve(result);tx.onabort=()=>reject(problem||tx.error||Error('ذخیره انجام نشد؛ فضای حافظه را بررسی کنید.'));tx.onerror=()=>{};}catch(e){if(tx)try{tx.abort();}catch{}reject(e);}});}
const meta=async(key,value)=>{if(value===undefined)return(await read('meta',key))?.value;await write(['meta'],tx=>tx.objectStore('meta').put({key,value}));return value;};
function bulk(store,rows,done){let i=0;function chunk(){let last;for(let n=Math.min(i+200,rows.length);i<n;i++)last=store.add(rows[i]);if(i<rows.length)last.onsuccess=chunk;else done?.();}chunk();}
function stopWorker(){worker?.terminate();worker=null;workerPromise=null;if(workerURL)URL.revokeObjectURL(workerURL);workerURL=null;for(const j of workerJobs.values()){clearTimeout(j.timer);j.reject(Error('پردازش فایل متوقف شد.'));}workerJobs.clear();}
async function getWorker(){if(worker)return worker;if(workerPromise)return workerPromise;workerPromise=(async()=>{const response=await fetch('excel-worker.js');if(!response.ok)throw Error('فایل پردازشگر داخل برنامه کامل نیست.');const blob=await response.blob();workerURL=URL.createObjectURL(new Blob([blob],{type:'text/javascript'}));worker=new Worker(workerURL);worker.onmessage=({data:m})=>{const j=workerJobs.get(m.id);if(!j)return;clearTimeout(j.timer);workerJobs.delete(m.id);m.error?j.reject(Error(m.error)):j.resolve(m.result);};worker.onerror=()=>stopWorker();return worker;})();try{return await workerPromise;}catch(e){stopWorker();throw e;}}
async function excelTask(type,data,transfer=[]){const w=await getWorker();return new Promise((resolve,reject)=>{const id=++workerJob,timer=setTimeout(()=>stopWorker(),180000);workerJobs.set(id,{resolve,reject,timer});w.postMessage({id,type,data},transfer);});}
function to64(buf){const a=new Uint8Array(buf);let s='';for(let i=0;i<a.length;i+=32768)s+=String.fromCharCode(...a.subarray(i,i+32768));return btoa(s);}
function from64(s){const t=atob(s),a=new Uint8Array(t.length);for(let i=0;i<t.length;i++)a[i]=t.charCodeAt(i);return a.buffer;}
const safe=s=>String(s||'انبار').replace(/[<>:"\\/|?*\x00-\x1f]/g,'-').slice(0,55);
async function saveFile(bytes,mime,name){return window.presentFileSave(bytes,mime,name);}
window.nativeSaveResult=(id,ok,message)=>{const job=nativeJobs.get(id);if(!job)return;nativeJobs.delete(id);ok?job.resolve():job.reject(Error(message||'ذخیره لغو شد.'));};
window.nativePickResult=(id,name,mime,data,error)=>{const job=nativeJobs.get(id);if(!job)return;nativeJobs.delete(id);error?job.reject(Error(error)):job.resolve(new File([from64(data)],name,{type:mime}));};
function nativePicker(input,kind){if(!window.AndroidFiles?.pick)return;input.onclick=guard(async e=>{e.preventDefault();const id=uid(),file=await new Promise((resolve,reject)=>{nativeJobs.set(id,{resolve,reject});window.AndroidFiles.pick(id,kind);});const dt=new DataTransfer();dt.items.add(file);input.files=dt.files;input.dispatchEvent(new Event('change',{bubbles:true}));toast('فایل انتخاب شد: '+file.name);});}
function showTab(tab){if(tab==='admin'&&profile?.role!=='admin')return;for(const section of document.querySelectorAll('section[id^="tab-"]'))section.hidden=section.id!=='tab-'+tab;for(const b of document.querySelectorAll('[data-tab]'))b.classList.toggle('active',b.dataset.tab===tab);if(tab==='count')$('search').focus();}
const scopeTitle=s=>`${s.companyName} · ${s.warehouseName} · ${s.periodName}`;
function renderSearch(){const q=$('search').value.trim();if(!q){$('results').innerHTML='<p class="empty">تگ، کد یا نام کالا را وارد کنید.</p>';return;}const found=index.search(q,$('searchMode').value,41);$('results').innerHTML=found.slice(0,40).map(p=>{const total=index.total(p.id,round);return`<div class="product"><div><h3>${esc(p.name)}</h3><div class="meta"><span>تگ: <code>${esc(p.tag||'—')}</code></span><span>کد: <code>${esc(p.code||'—')}</code></span></div><span class="badge">این دستگاه: ${total===null?'شمارش نشده':fmt(total/1000)}</span></div><button class="primary" data-pick="${esc(p.id)}">شمارش</button></div>`;}).join('')||'<p class="empty">کالایی پیدا نشد.</p>';if(found.length>40)$('results').insertAdjacentHTML('beforeend','<p class="hint">۴۰ نتیجه اول؛ عبارت دقیق‌تری وارد کنید.</p>');}
function needScope(){if(!current)throw Error('ابتدا شرکت، انبار و دوره را انتخاب کنید.');}
function countModal(pid){needScope();const p=index.products.get(pid);if(!p)return;selected=pid;entryLimit=30;modal('ثبت شمارش روی همین دستگاه',`<h3>${esc(p.name)}</h3><div class="meta"><span>کد: <code>${esc(p.code||'—')}</code></span><span>تگ: <code>${esc(p.tag||'—')}</code></span></div>${p.stock!==''?`<span class="stock">موجودی سیستم: ${esc(p.stock)}</span>`:''}<div class="total"><span>جمع این دستگاه · نوبت ${fmt(round)}</span><b>${index.total(pid,round)===null?'—':fmt(index.total(pid,round)/1000)}</b></div><label>تعداد این بخش<input id="quantity" class="quantity" inputmode="decimal" autocomplete="off"></label><button id="calcToggle" class="secondary wide">ماشین‌حساب</button><div id="calculator" hidden><div class="calc-screen" id="calcScreen">0</div><div class="calc">${['7','8','9','/','4','5','6','*','1','2','3','-','C','0','.','+','=','←'].map(x=>`<button data-calc="${x}">${x}</button>`).join('')}</div><button id="useCalc" class="secondary wide">انتقال به تعداد</button></div><p id="countError" class="error" hidden></p><button id="saveCount" class="primary wide">ثبت و افزودن به جمع قبلی</button><div id="entryList"></div>`);$('saveCount').onclick=guard(saveCount);$('calcToggle').onclick=()=>$('calculator').hidden=!$('calculator').hidden;$('useCalc').onclick=guard(()=>{$('quantity').value=String(Math.round(arithmetic($('calcScreen').textContent)*1000)/1000);$('calculator').hidden=true;});renderEntries();$('quantity').focus();}
function renderEntries(){const list=index.group(selected,round);$('entryList').innerHTML=list.length?'<h2 style="margin-top:20px">ثبت‌های همین دستگاه</h2>'+list.slice(0,entryLimit).map(e=>`<div class="entry"><div class="entry-top"><b>${fmt(e.qtyMilli/1000)} · ${esc(e.operator)}</b><button data-edit="${e.id}" class="secondary">اصلاح همین ثبت</button></div><small>${date(e.createdAt)} · ${e.pending?'منتظر ارسال':'ارسال شده'}${e.revision>1?' · اصلاح '+fmt(e.revision-1):''}</small><div id="edit-${e.id}"></div></div>`).join('')+(list.length>entryLimit?'<button id="moreEntries" class="secondary wide">ثبت‌های قدیمی‌تر</button>':''):'';if($('moreEntries'))$('moreEntries').onclick=()=>{entryLimit+=30;renderEntries();};}
async function saveCount(){if(busy||!selected)return;const scopeId=current.id,pid=selected,r=round,n=qty($('quantity').value);if(current.closed)throw Error('این دوره در مرکز بسته است.');busy=true;$('saveCount').disabled=true;try{const now=new Date().toISOString(),e={id:uid(),deviceId,scopeId,productId:pid,round:r,qtyMilli:n,operator:profile.name,createdAt:now,updatedAt:now,revision:1,syncedRevision:0,changes:[],pending:1};const group=await write(['entries'],(tx,done,stop)=>{const store=tx.objectStore('entries'),req=store.index('scopeProductRound').getAll([scopeId,pid,r]);req.onsuccess=()=>{if(req.result.reduce((n,e)=>n+e.qtyMilli,0)+n>MAX){stop(Error('جمع تعداد بیش از حد مجاز است.'));return;}store.add(e);done([...req.result,e]);};});index.replaceGroup(pid,r,group);busy=false;closeModal();$('search').value='';render();toast('شمارش روی این دستگاه ذخیره شد.');syncAll();}finally{busy=false;if($('saveCount'))$('saveCount').disabled=false;}}
function editEntry(id){const e=index.entries.get(id);if(!e||busy)return;$('edit-'+id).innerHTML=`<label>تعداد اصلاح‌شده<input id="value-${id}" inputmode="decimal" value="${e.qtyMilli/1000}"></label><button id="correct-${id}" class="primary wide">ذخیرهٔ اصلاح</button>`;$('correct-'+id).onclick=guard(()=>correctEntry(e));}
async function correctEntry(prior){if(busy)return;if(current?.closed)throw Error('این دوره در مرکز بسته است.');const n=qty($('value-'+prior.id).value);busy=true;try{const group=await write(['entries'],(tx,done,stop)=>{const store=tx.objectStore('entries'),r=store.get(prior.id);r.onsuccess=()=>{const e=r.result;if(!e||e.revision!==prior.revision){stop(Error('این ثبت تغییر کرده؛ فرم را دوباره باز کنید.'));return;}const g=store.index('scopeProductRound').getAll([e.scopeId,e.productId,e.round]);g.onsuccess=()=>{if(g.result.reduce((n,x)=>n+x.qtyMilli,0)-e.qtyMilli+n>MAX){stop(Error('جمع تعداد بیش از حد مجاز است.'));return;}const updated={...e,qtyMilli:n,revision:e.revision+1,updatedAt:new Date().toISOString(),pending:1,changes:[...e.changes,{at:new Date().toISOString(),by:profile.name,from:e.qtyMilli,to:n}]};store.put(updated);done(g.result.map(x=>x.id===e.id?updated:x));};};});index.replaceGroup(prior.productId,prior.round,group);busy=false;render();countModal(prior.productId);toast('همین ثبت اصلاح شد؛ بقیه ثبت‌ها محفوظ‌اند.');syncAll();}finally{busy=false;}}
function arithmetic(expr){const s=en(expr).replace(/\s/g,'');if(!/^\d+(?:\.\d+)?(?:[+*/-]\d+(?:\.\d+)?)*$/.test(s))throw Error('عبارت ماشین‌حساب کامل نیست.');const p=s.match(/\d+(?:\.\d+)?|[+*/-]/g).map(x=>/^\d/.test(x)?Number(x):x);for(let i=1;i<p.length-1;)if(p[i]==='*'||p[i]==='/'){p.splice(i-1,3,p[i]==='*'?p[i-1]*p[i+1]:p[i-1]/p[i+1]);i=1;}else i+=2;let n=p[0];for(let i=1;i<p.length;i+=2)n=p[i]==='+'?n+p[i+1]:n-p[i+1];if(!Number.isFinite(n)||n<0)throw Error('حاصل باید معتبر و غیرمنفی باشد.');return n;}
function manual(){needScope();modal('افزودن کالای خارج از فایل',`<label>نام کالا<input id="manualName" maxlength="500"></label><label>کد (اختیاری)<input id="manualCode" maxlength="100"></label><label>تگ (اختیاری)<input id="manualTag" maxlength="100"></label><button id="saveManual" class="primary wide">افزودن و شمارش</button>`);$('saveManual').onclick=guard(async()=>{if(busy)return;const name=$('manualName').value.trim(),code=$('manualCode').value.trim(),tag=$('manualTag').value.trim();if(!name)throw Error('نام کالا را وارد کنید.');const key=tag?'t:'+ident(tag):code?'c:'+norm(code):'n:'+norm(name);if(index.products.has(key))throw Error('این کالا وجود دارد؛ تگ، کد یا نام آن را جست‌وجو کنید.');if(products.length>=20000)throw Error('حداکثر ۲۰۰۰۰ کالا مجاز است.');const p={id:key,key,name,code,tag,stock:'',sourceRow:null};busy=true;$('saveManual').disabled=true;try{const merged=await write(['catalogs','scopes'],(tx,done,stop)=>{const store=tx.objectStore('catalogs'),r=store.get(current.id);r.onsuccess=()=>{const list=r.result?.products||[];if(list.some(x=>x.id===p.id)){stop(Error('این کالا قبلاً اضافه شده است؛ آن را جست‌وجو کنید.'));return;}if(list.length>=20000){stop(Error('حداکثر ۲۰۰۰۰ کالا مجاز است.'));return;}const next=[...list,p];store.put({scopeId:current.id,products:next});tx.objectStore('scopes').put({...current,productCount:next.length});done(next);};});products=merged;index.addProduct(p);current.productCount=products.length;busy=false;render();countModal(p.id);}finally{busy=false;if($('saveManual'))$('saveManual').disabled=false;}});}

async function beginImport(){if(busy||staged)return;needScope();if(products.length)throw Error('برای حفظ شمارش‌ها، فایل این انبار قابل جایگزینی نیست؛ انبار یا عنوان شمارش دیگری بسازید.');const file=$('rawFile').files[0];if(!file||!file.name.toLowerCase().endsWith('.xlsx'))throw Error('فایل XLSX را انتخاب کنید.');if(file.size>15*1024*1024)throw Error('حداکثر حجم فایل خام ۱۵ مگابایت است.');const sid=current.id;busy=true;try{const bytes=await file.arrayBuffer(),view=await excelTask('inspect',{bytes,fileName:file.name},[bytes]);staged={...view,target:'local',sid};showMapping();}catch(e){stopWorker();throw e;}finally{busy=false;}}
function showMapping(){const s=staged,m=s.mapping;modal('تأیید ستون‌های اکسل',`<p class="hint">نام کالا الزامی است؛ کد، تگ و موجودی سیستم را بررسی کنید. صفرهای ابتدای کد حفظ می‌شوند.</p><label>برگه<select id="mapSheet">${s.sheets.map(w=>`<option value="${w.id}" ${m.sheetId===w.id?'selected':''}>${esc(w.name)}</option>`).join('')}</select></label><label>ردیف عنوان<input id="headerRow" type="number" min="1" max="100" value="${m.headerRow}"></label><div class="mapping">${[['name','نام کالا'],['code','کد کالا'],['tag','شماره تگ'],['stock','موجودی سیستم']].map(([key,label])=>`<label>${label}<select id="map-${key}"><option value="">انتخاب نشده</option>${s.headings.map((h,i)=>`<option value="${i+1}" ${m[key]===i+1?'selected':''}>${i+1}: ${esc(h||'بدون عنوان')}</option>`).join('')}</select></label>`).join('')}</div><div class="preview"><table>${s.rows.map(row=>'<tr>'+row.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')}</table></div><button id="confirmImport" class="primary wide">تأیید و ورود کالاها</button>`);const update=guard(async(sheetId,headerRow)=>{if(busy)return;busy=true;$('confirmImport').disabled=true;try{const view=await excelTask('preview',{sheetId,headerRow});staged={...view,target:s.target,sid:s.sid};showMapping();}finally{busy=false;}});$('mapSheet').onchange=()=>update(Number($('mapSheet').value),1);$('headerRow').onchange=()=>{const r=Number($('headerRow').value);if(Number.isInteger(r)&&r>0&&r<=100)update(Number($('mapSheet').value),r);};$('confirmImport').onclick=guard(commitImport);}
async function commitImport(){if(busy)return;const s=staged,m={sheetId:Number($('mapSheet').value),headerRow:Number($('headerRow').value)};for(const k of ['name','code','tag','stock'])m[k]=$('map-'+k).value?Number($('map-'+k).value):null;const cols=Object.values(m).slice(2).filter(Boolean);if(!m.name||new Set(cols).size!==cols.length)throw Error('ستون نام کالا و ستون‌های جداگانه را مشخص کنید.');busy=true;$('confirmImport').disabled=true;try{const value=await excelTask('parse',m);await write(['scopes','catalogs','raw'],(tx,done,stop)=>{const req=tx.objectStore('catalogs').get(s.sid);req.onsuccess=()=>{if(req.result?.products?.length){stop(Error('فایل قبلاً وارد شده است.'));return;}const local=scopes.find(x=>x.id===s.sid);tx.objectStore('catalogs').put({scopeId:s.sid,products:value.products});tx.objectStore('raw').put({scopeId:s.sid,...value.raw});tx.objectStore('scopes').put({...local,fileName:value.raw.fileName,productCount:value.products.length});};});staged=null;stopWorker();busy=false;closeModal();await refreshScopes(s.target==='local'?s.sid:undefined);renderCompanies();toast('فایل خام با موفقیت وارد شد.');queueMicrotask(syncAll);}finally{busy=false;if($('confirmImport'))$('confirmImport').disabled=false;}}
async function snapshot(sid){const s=await read('scopes',sid),c=await read('catalogs',sid),r=await read('raw',sid),entries=await read('entries',sid,'scopeId');return{settings:{companyName:s.companyName,warehouse:s.warehouseName,period:s.periodName,operator:profile.name},products:c?.products||[],raw:r?{fileName:r.fileName,bytes:r.bytes,mapping:r.mapping}:null,entries};}
async function packetExport(){needScope();if(busy)return;busy=true;try{const s=await snapshot(current.id),data={format:'inventory-hybrid-packet-v1',deviceId,scope:{companyName:current.companyName,warehouseName:current.warehouseName,periodName:current.periodName,central:current.central},products:s.products,entries:s.entries};const buffer=await excelTask('packetEncode',data);stopWorker();await saveFile(buffer,'application/json',`شمارش-گوشی-${safe(current.warehouseName)}-${Date.now()}.json`);toast('فایل تبادل این دستگاه ذخیره شد.');}finally{stopWorker();busy=false;}}
async function acknowledge(scopeId,acks){await write(['entries'],tx=>{const store=tx.objectStore('entries');for(const a of acks){const r=store.get(a.id);r.onsuccess=()=>{const e=r.result;if(!e||e.scopeId!==scopeId)return;e.syncedRevision=Math.max(e.syncedRevision||0,a.revision);e.pending=e.revision===a.revision?0:1;store.put(e);};}});if(current?.id===scopeId)for(const a of acks){const e=index.entries.get(a.id);if(e){e.syncedRevision=Math.max(e.syncedRevision||0,a.revision);e.pending=e.revision===a.revision?0:1;}}}
// One built-in center. The phone never needs a URL or network setup.
const CENTER='https://script.google.com/macros/s/AKfycbz2iQyWRCWUV45KyB_mg9clw6aphim4GGluMcmImFKaeTL4N_ONmGN8r6m8BSEW43Xl/exec';
let companyDirectory=[],selecting=false,loginBusy=false;
function connection(){const c=profile?conns[profile.role]:null;return c?.protocol==='inventory-hybrid-v2'?c:null;}
window.nativeHTTPResult=(id,status,body,error)=>{const j=httpJobs.get(id);if(!j)return;httpJobs.delete(id);clearTimeout(j.timer);if(error){j.reject(Error(error));return;}try{const r=JSON.parse(body);if(!r.ok){const e=Error(r.error||'مرکز پاسخ کامل نداد.');e.status=r.status||status;throw e;}j.resolve(r.data);}catch(e){j.reject(e instanceof SyntaxError?Error('پاسخ مرکز قابل خواندن نیست؛ شمارش گوشی محفوظ است.'):e);}};
async function rpc(action,body={},token=connection()?.token||'',timeoutMs=90000){
 const payload=JSON.stringify({protocol:'inventory-hybrid-v2',action,body,token});
 if(window.AndroidNetwork?.rpc){const id=uid();return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{httpJobs.delete(id);reject(Error('مرکز پاسخ نداد؛ شمارش روی گوشی محفوظ است.'));},100000);httpJobs.set(id,{resolve,reject,timer});window.AndroidNetwork.rpc(id,payload);});}
 const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),timeoutMs);try{const response=await fetch(CENTER,{method:'POST',headers:{'Content-Type':'text/plain;charset=UTF-8'},body:payload,credentials:'omit',signal:ctrl.signal}),r=await response.json();if(!r.ok){const e=Error(r.error||'مرکز پاسخ کامل نداد.');e.status=r.status||response.status;throw e;}return r.data;}finally{clearTimeout(timer);}
}
function options(items,key='id',label=x=>x.name){return '<option value="">انتخاب کنید</option>'+items.map(x=>`<option value="${esc(x[key])}">${esc(label(x))}</option>`).join('');}
async function cacheRemote(){const c=connection();if(c?.namespace&&remote)await meta('remote:'+c.namespace,remote);}
function allCompanies(){const names=new Map();for(const c of [...companyDirectory,...(remote?.companies||[]),...scopes.map(s=>({name:s.companyName}))])if(!names.has(norm(c.name)))names.set(norm(c.name),{id:norm(c.name),name:c.name});return [...names.values()];}
function choices(){const list=[...scopes];for(const s of remote?.scopes||[])if(!scopes.some(l=>l.central?.namespace===remote.namespace&&l.central.scopeId===s.id))list.push({...s,id:'remote:'+s.id,remoteId:s.id});return list;}
function renderCompanies(){const companies=allCompanies(),old=$('companySelect').value,adminOld=$('adminCompany').value;$('companySelect').innerHTML=options(companies);$('adminCompany').innerHTML=options(companies);if(companies.some(c=>c.id===old))$('companySelect').value=old;else if(current)$('companySelect').value=norm(current.companyName);if(companies.some(c=>c.id===adminOld))$('adminCompany').value=adminOld;else $('adminCompany').value=$('companySelect').value;renderScopeOptions();renderAdminLists();}
function renderScopeOptions(prefer){const co=$('companySelect').value,old=prefer||current?.id||$('localScope').value,list=choices().filter(s=>norm(s.companyName)===co);$('localScope').innerHTML=options(list,'id',s=>s.warehouseName+' · '+s.periodName+(s.closed?' · بسته':''));if(list.some(s=>s.id===old))$('localScope').value=old;}
function renderAdminLists(){const co=$('adminCompany').value,old=$('adminWarehouse').value,list=choices().filter(s=>norm(s.companyName)===co);$('adminWarehouse').innerHTML=options(list,'id',s=>s.warehouseName+' · '+s.periodName);if(list.some(s=>s.id===old))$('adminWarehouse').value=old;else if(current&&norm(current.companyName)===co)$('adminWarehouse').value=current.id;$('adminMessage').textContent=connection()?.token?'با دسترسی به اینترنت، فایل و شمارش‌ها خودکار به مرکز ارسال می‌شوند.':'برای مدیریت شرکت و انبار، به اینترنت و ورود مدیر وب نیاز است.';}
async function refreshScopes(prefer){scopes=await read('scopes');scopes.sort((a,b)=>scopeTitle(a).localeCompare(scopeTitle(b),'fa'));const id=prefer||current?.id||await meta('lastScope')||'';renderCompanies();const found=scopes.find(s=>s.id===id);if(found){$('companySelect').value=norm(found.companyName);renderScopeOptions(id);if(prefer||!current||current.id!==id)await selectScope(id);else{current=found;render();}}else if(!current)render();}
async function selectScope(id){
 if(busy)throw Error('ابتدا عملیات فایل را تمام کنید.');if(selecting)return;
 if(id.startsWith('remote:')){selecting=true;try{const sid=id.slice(7),data=await rpc('download',{scopeId:sid}),c=connection();if(!c||c.namespace!==remote.namespace)throw Error('ورود مرکز تغییر کرد؛ دوباره انتخاب کنید.');if(!data.products.length&&profile?.role!=='admin')throw Error('فایل خام این انبار هنوز توسط مدیر وارد نشده است.');const s={id:uid(),companyName:data.scope.companyName,warehouseName:data.scope.warehouseName,periodName:data.scope.periodName,closed:data.scope.closed,productCount:data.products.length,fileName:data.raw?.fileName||'',central:{namespace:c.namespace,scopeId:sid},catalogVersion:data.scope.version};await write(['scopes','catalogs','raw'],(tx,done,stop)=>{const r=tx.objectStore('scopes').getAll();r.onsuccess=()=>{if(r.result.some(x=>x.central?.namespace===c.namespace&&x.central.scopeId===sid)){stop(Error('این انبار قبلاً دریافت شده است.'));return;}tx.objectStore('scopes').add(s);tx.objectStore('catalogs').put({scopeId:s.id,products:data.products});if(data.raw)tx.objectStore('raw').put({scopeId:s.id,...data.raw,bytes:from64(data.raw.bytes)});};});id=s.id;scopes=await read('scopes');toast('فایل مدیر روی گوشی ذخیره شد؛ آفلاین هم قابل استفاده است.');}finally{selecting=false;}}
 current=scopes.find(s=>s.id===id)||null;selected=null;products=[];raw=null;index.rebuild([],[]);if(current){const c=await read('catalogs',id);products=c?.products||[];index.rebuild(products,await read('entries',id,'scopeId'));await meta('lastScope',id);$('companySelect').value=norm(current.companyName);}renderCompanies();renderScopeOptions(id);render();
}
function render(){ $('chooseDestination').hidden=!current||!connection()?.token||current.central?.namespace===connection()?.namespace;const list=[...index.entries.values()];$('productCount').textContent=fmt(products.length);$('localCount').textContent=fmt(index.roundCounts[round]||0);$('pendingCount').textContent=fmt(list.filter(e=>e.pending).length);$('scopeInfo').textContent=current?(current.closed?'این دوره در مرکز بسته است.':current.central?'فایل این انبار روی گوشی ذخیره شده است.':'این انبار روی گوشی آماده است؛ ارسال به مرکز با ورود و دسترسی به اینترنت انجام می‌شود.'):'با اینترنت شرکت و انبار مدیر را انتخاب کنید؛ بدون اینترنت، در «فایل و خروجی» انبار خودتان را بسازید.';$('rawStatus').textContent=current?.fileName?'فایل: '+current.fileName:'هنوز فایل خامی برای این انبار روی گوشی نیست.';renderSearch();$('recent').innerHTML=index.recent(profile?.name,round).map(e=>{const p=index.products.get(e.productId);return p?`<div class="recent-item"><div><h3>${esc(p.name)}</h3><div class="meta">${date(e.createdAt)} · ${e.pending?'ارسال‌نشده':'ارسال شده'}</div></div><button class="secondary" data-pick="${esc(p.id)}">${fmt(e.qtyMilli/1000)}</button></div>`:'';}).join('')||'<p class="empty">هنوز شمارشی در این نوبت ثبت نکرده‌اید.</p>';}
async function showManagerLogin(){if(!$('loginName').value.trim())throw Error('نام خود را وارد کنید.');$('managerPinForm').hidden=false;$('managerPin').focus();}
async function managerConfirm(){if(loginBusy)return;const secret=$('managerPin').value,name=$('loginName').value.trim();if(!secret||!name)throw Error('نام و رمز مدیر وب را وارد کنید.');loginBusy=true;$('confirmManager').disabled=true;$('confirmManager').textContent='در حال ورود به مرکز…';try{const result=await rpc('login',{role:'admin',name,secret,deviceId},'');await acceptConnection('admin',result);await meta('remote:'+result.namespace,result.catalog);await login('admin');}catch(e){throw Error(e.status===401?'رمز مدیر وب درست نیست.':'ورود مدیر به اینترنت نیاز دارد. برای شمارش آفلاین، ورود شمارشگر را بزنید.');}finally{loginBusy=false;$('confirmManager').disabled=false;$('confirmManager').textContent='ورود';}}
async function acceptConnection(role,result){conns[role]={protocol:'inventory-hybrid-v2',url:CENTER,token:result.token,role,namespace:result.namespace};await meta('connections',conns);}
async function connectSecret(secret){if(!profile)return;const active=profile,r=await rpc('login',{role:active.role,name:active.name,secret,deviceId},'');if(profile!==active)return;await acceptConnection(active.role,r);remote=r.catalog;await cacheRemote();renderCompanies();$('centerLogin').hidden=true;await syncAll();}
function centerError(e){$('syncStatus').textContent=(e.status===401?'رمز مرکز یا کد تیم درست نیست.':e.message)+' شمارش و خروجی گوشی فعال است.';$('connectionStatus').textContent='ذخیره روی گوشی';$('connectionStatus').className='badge wait';$('centerLogin').hidden=false;}
function connect(){if(!profile)return;modal(profile.role==='admin'?'ورود مدیر وب':'ورود تیم به مرکز',`<p class="hint">مرکز از قبل داخل برنامه تنظیم شده است.</p><label>${profile.role==='admin'?'رمز مدیر وب':'کد تیم'}<input id="centerSecret" type="password" autocomplete="current-password"></label><button id="connectCenter" class="primary wide">ورود</button>`);$('connectCenter').onclick=guard(async()=>{const secret=$('centerSecret').value;if(!secret)throw Error('رمز یا کد را وارد کنید.');$('connectCenter').disabled=true;try{await connectSecret(secret);closeModal();toast('به همان مرکز وب متصل شدید.');}finally{if($('connectCenter'))$('connectCenter').disabled=false;}});}
async function login(role){const name=$('loginName').value.trim();if(!name||name.length>80)throw Error('نام خود را وارد کنید.');profile={role,name};await meta('lastName',name);$('login').hidden=true;$('workspace').hidden=false;$('managerPin').value='';$('managerPinForm').hidden=true;$('accountLabel').textContent=(role==='admin'?'مدیر':'شمارشگر')+' · '+name;$('adminTab').hidden=role!=='admin';companyDirectory=await meta('simpleCompanies')||[];const c=connection();remote=c?.namespace?await meta('remote:'+c.namespace):null;$('centerLogin').hidden=!!c?.token;await refreshScopes();showTab(role==='admin'&&!scopes.length?'admin':'count');syncAll();}
async function addCompany(){if(profile?.role!=='admin')throw Error('فقط مدیر می‌تواند شرکت بسازد.');modal('افزودن شرکت','<label>نام شرکت<input id="entityName" maxlength="100"></label><button id="saveEntity" class="primary wide">ذخیره شرکت</button>');$('saveEntity').onclick=guard(async()=>{if(busy)return;const name=$('entityName').value.trim();if(!name)throw Error('نام شرکت را وارد کنید.');if(allCompanies().some(c=>norm(c.name)===norm(name)))throw Error('شرکت با این نام وجود دارد.');busy=true;try{await rpc('company',{name});companyDirectory=await write(['meta'],(tx,done,stop)=>{const store=tx.objectStore('meta'),r=store.get('simpleCompanies');r.onsuccess=()=>{const list=r.result?.value||[];if([...list,...(remote?.companies||[]),...scopes.map(s=>({name:s.companyName}))].some(c=>norm(c.name)===norm(name))){stop(Error('شرکت با این نام وجود دارد.'));return;}list.push({name});store.put({key:'simpleCompanies',value:list});done(list);};});busy=false;closeModal();renderCompanies();$('adminCompany').value=norm(name);$('companySelect').value=norm(name);renderScopeOptions();renderAdminLists();toast('شرکت ساخته شد؛ حالا انبار اضافه کنید.');syncAll();}finally{busy=false;}});}
function newLocal(){const selectedCompany=allCompanies().find(c=>c.id===$('adminCompany').value)?.name||current?.companyName||'',periods=[...new Set([...(remote?.scopes||[]).filter(s=>!s.closed).map(s=>s.periodName),...scopes.map(s=>s.periodName)])],defaultPeriod=periods[0]||'شمارش جاری';modal('افزودن انبار',`<label>شرکت<input id="localCompany" maxlength="100" value="${esc(selectedCompany)}" list="companyNames"><datalist id="companyNames">${allCompanies().map(c=>`<option value="${esc(c.name)}">`).join('')}</datalist></label><label>نام انبار<input id="localWarehouse" maxlength="100"></label><label>عنوان شمارش<input id="localPeriod" maxlength="100" value="${esc(defaultPeriod)}" list="periodNames"><datalist id="periodNames">${periods.map(p=>`<option value="${esc(p)}">`).join('')}</datalist></label><button id="createLocal" class="primary wide">ذخیره انبار</button>`);$('createLocal').onclick=guard(async()=>{if(busy)return;const values=['localCompany','localWarehouse','localPeriod'].map(id=>$(id).value.trim());if(values.some(s=>!s))throw Error('نام شرکت، انبار و عنوان شمارش را وارد کنید.');const s={id:uid(),companyName:values[0],warehouseName:values[1],periodName:values[2],central:null,closed:0,productCount:0,fileName:''};busy=true;try{if(profile?.role==='admin'){const result=await rpc('provision',{companyName:s.companyName,warehouseName:s.warehouseName,periodName:s.periodName});s.central={namespace:result.namespace,scopeId:result.scope.id};s.closed=result.scope.closed;}await write(['scopes'],(tx,done,stop)=>{const store=tx.objectStore('scopes'),r=store.getAll();r.onsuccess=()=>{if(r.result.some(x=>[x.companyName,x.warehouseName,x.periodName].map(norm).join('|')===values.map(norm).join('|'))){stop(Error('این انبار در این شمارش وجود دارد.'));return;}store.add(s);};});busy=false;closeModal();await refreshScopes(s.id);showTab('files');toast('انبار ساخته شد؛ فایل خام را انتخاب کنید.');syncAll();}finally{busy=false;}});}
async function exportExcel(central=false){needScope();if(busy)return;busy=true;try{let s;if(central){if(!current.central||current.central.namespace!==connection()?.namespace)throw Error('این انبار هنوز به مرکز ارسال نشده است.');const data=await rpc('download',{scopeId:current.central.scopeId,snapshot:true});s={settings:{companyName:data.scope.companyName,warehouse:data.scope.warehouseName,period:data.scope.periodName},products:data.products,entries:data.entries,raw:data.raw?{...data.raw,bytes:from64(data.raw.bytes)}:null};}else s=await snapshot(current.id);if(!s.products.length)throw Error('هنوز فایل کالا وارد نشده است.');toast('در حال ساخت اکسل…');const buffer=await excelTask('export',s,s.raw?[s.raw.bytes]:[]);stopWorker();await saveFile(buffer,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',`${central?'تجمیعی':'این-گوشی'}-${safe(s.settings.companyName)}-${safe(s.settings.warehouse)}-${safe(s.settings.period)}.xlsx`);toast('خروجی آماده شد؛ ذخیره در Files را بررسی کنید.');}finally{stopWorker();busy=false;}}
async function syncAll(){
 if(syncing||busy||!profile||!connection()?.token)return;syncing=true;const c=connection(),active=profile,errors=[],send=(action,body={})=>{if(profile!==active||connection()!==c)throw Error('ورود تغییر کرد.');return rpc(action,body,c.token);};
 try{let info=await send('catalog');if(profile!==active||connection()!==c)return;if(info.namespace!==c.namespace)throw Error('شناسه مرکز تغییر کرده است؛ دوباره وارد مرکز شوید.');remote=info;await cacheRemote();renderCompanies();
  if(active.role==='admin')for(const co of companyDirectory)if(!info.companies.some(x=>norm(x.name)===norm(co.name)))await send('company',{name:co.name});
  for(const s of await read('scopes')){if(profile!==active||connection()!==c)return;try{
   if(s.central&&s.central.namespace!==c.namespace){if((await read('entries',s.id,'scopeId')).some(e=>e.syncedRevision))continue;s.central=null;}
   const cat=await read('catalogs',s.id),list=cat?.products||[];
   if(!s.central){let match=info.scopes.filter(x=>[x.companyName,x.warehouseName,x.periodName].map(norm).join('|')===[s.companyName,s.warehouseName,s.periodName].map(norm).join('|'));if(match.length>1)throw Error('چند انبار هم‌نام در مرکز وجود دارد؛ مقصد مشخص نیست.');let target=match[0];
    if(active.role==='admin'&&(!target||(!target.productCount&&list.length))){const r=await read('raw',s.id),result=await send('provision',{companyName:s.companyName,warehouseName:s.warehouseName,periodName:s.periodName,...(list.length&&r?{products:list,raw:{...r,bytes:to64(r.bytes)}}:{})});target=result.scope;}
    if(!target)continue;
    if(list.length){const data=await send('download',{scopeId:target.id}),keys=new Map(data.products.map(p=>[p.id,p]));if(list.some(p=>p.sourceRow!==null&&(!keys.has(p.id)||(p.code&&keys.get(p.id).code&&norm(p.code)!==norm(keys.get(p.id).code)))))throw Error('فایل گوشی با فایل مرکز یکسان نیست؛ شمارش‌ها ارسال نشدند.');}
    s.central={namespace:c.namespace,scopeId:target.id};s.closed=target.closed;await write(['scopes'],tx=>tx.objectStore('scopes').put(s));
   }
   const target=info.scopes.find(x=>x.id===s.central.scopeId);if(target&&s.closed!==target.closed){s.closed=target.closed;await write(['scopes'],tx=>tx.objectStore('scopes').put(s));}
   // An admin may import a local file after the empty warehouse was published.
   if(active.role==='admin'&&target&&!target.productCount&&list.length){const r=await read('raw',s.id);if(r)await send('provision',{companyName:s.companyName,warehouseName:s.warehouseName,periodName:s.periodName,products:list,raw:{...r,bytes:to64(r.bytes)}});}
   const pending=(await read('entries',s.id,'scopeId')).filter(e=>e.pending);if(s.closed&&pending.length)throw Error('دوره در مرکز بسته است؛ ثبت‌های ارسال‌نشده روی گوشی مانده‌اند.');for(let i=0;i<pending.length;i+=50){if(profile!==active||connection()!==c)return;const result=await send('sync',{namespace:c.namespace,deviceId,scopeId:s.central.scopeId,entries:pending.slice(i,i+50),manualProducts:list.filter(p=>p.sourceRow===null)});await acknowledge(s.id,result.acknowledgements);}
  }catch(e){errors.push(s.warehouseName+': '+e.message);}}
  if(profile!==active||connection()!==c)return;info=await send('catalog');remote=info;await cacheRemote();const waiting=(await read('entries',1,'pending')).length;$('connectionStatus').textContent=waiting?'ذخیره روی گوشی · '+fmt(waiting)+' در صف':'متصل به مرکز';$('connectionStatus').className='badge'+(waiting?' wait':'');$('syncStatus').textContent=errors.length?errors.join(' · '):waiting?'شمارش‌ها روی گوشی محفوظ‌اند؛ ارسال انبارهای آماده ادامه دارد.':'ارسال‌ها تأیید شده‌اند · '+new Date().toLocaleTimeString('fa-IR');$('centerLogin').hidden=false;$('centerLogin').textContent='ورود مرکز';await refreshScopes();
 }catch(e){if(e.status===401&&connection()===c){c.token='';await meta('connections',conns);}if(profile===active)centerError(e);}finally{syncing=false;}
}
function chooseDestination(){needScope();if(!connection()?.token)throw Error('ابتدا با کد تیم وارد مرکز شوید.');const available=(remote?.scopes||[]).filter(s=>!s.closed&&s.productCount);modal('انتخاب انبار مرکزی',`<p>شمارش همین گوشی برای کدام انبار است؟</p><label>شرکت و انبار<select id="destination">${options(available,'id',scopeTitle)}</select></label><button id="confirmDestination" class="primary wide">تأیید مقصد ارسال</button>`);$('confirmDestination').onclick=guard(async()=>{const sid=$('destination').value;if(!sid)throw Error('انبار مقصد را انتخاب کنید.');const local=current,c=connection();if((await read('entries',local.id,'scopeId')).some(e=>e.syncedRevision))throw Error('شمارش این انبار قبلاً ارسال شده و مقصد آن تغییر نمی‌کند.');const data=await rpc('download',{scopeId:sid}),cat=await read('catalogs',local.id),keys=new Map(data.products.map(p=>[p.id,p]));if((cat?.products||[]).some(p=>p.sourceRow!==null&&(!keys.has(p.id)||(p.code&&keys.get(p.id).code&&norm(p.code)!==norm(keys.get(p.id).code)))))throw Error('کالاهای فایل گوشی با این انبار یکسان نیستند؛ هیچ شمارشی ارسال نشد.');if(!confirm('ارسال شمارش این گوشی به '+scopeTitle(data.scope)+'؟'))return;const updated={...local,central:{namespace:c.namespace,scopeId:sid},closed:data.scope.closed};await write(['scopes'],tx=>tx.objectStore('scopes').put(updated));current=updated;closeModal();await refreshScopes();await syncAll();});}
async function packetImport(){if(profile?.role!=='admin'||!connection()?.token)throw Error('با رمز مدیر وب وارد مرکز شوید.');needScope();if(!current.central||current.central.namespace!==connection().namespace)throw Error('این انبار هنوز به مرکز متصل نشده است.');const file=$('packetFile').files[0];if(!file)throw Error('فایل تبادل گوشی را انتخاب کنید.');if(file.size>40*1024*1024)throw Error('فایل بیش از اندازه بزرگ است.');if(busy)return;busy=true;try{const bytes=await file.arrayBuffer(),data=await excelTask('packetDecode',bytes,[bytes]);stopWorker();if(data.format!=='inventory-hybrid-packet-v1'||!Array.isArray(data.entries)||!Array.isArray(data.products))throw Error('فایل تبادل معتبر نیست.');if(data.scope.central?.namespace&&data.scope.central.namespace!==connection().namespace)throw Error('فایل به مرکز دیگری تعلق دارد.');if([data.scope.companyName,data.scope.warehouseName,data.scope.periodName].map(norm).join('|')!==[current.companyName,current.warehouseName,current.periodName].map(norm).join('|'))throw Error('نام شرکت، انبار یا عنوان شمارش فایل با انبار انتخاب‌شده یکسان نیست.');for(let i=0;i<data.entries.length;i+=50)await rpc('sync',{namespace:connection().namespace,deviceId:data.deviceId,scopeId:current.central.scopeId,entries:data.entries.slice(i,i+50),manualProducts:data.products.filter(p=>p.sourceRow===null)});toast('فایل در مرکز ثبت شد؛ شمارش تکراری دوباره اضافه نشد.');}finally{stopWorker();busy=false;}}
async function init(){
 for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>showTab(b.dataset.tab);$('closeModal').onclick=closeModal;$('modal').addEventListener('cancel',e=>{if(preparedCancel){e.preventDefault();preparedCancel();}else if(busy)e.preventDefault();else{selected=null;if(staged){staged=null;stopWorker();}}});
 $('workerLogin').onclick=guard(async()=>{const secret=$('loginCode').value;await login('worker');$('loginCode').value='';if(secret)connectSecret(secret).catch(centerError);});$('managerLogin').onclick=guard(showManagerLogin);$('confirmManager').onclick=guard(managerConfirm);
 $('logout').onclick=()=>{if(busy){toast('ابتدا عملیات فایل را تمام کنید.');return;}profile=null;remote=null;current=null;$('workspace').hidden=true;$('login').hidden=false;$('connectionStatus').textContent='حافظه گوشی';};
 $('companySelect').onchange=guard(async()=>{renderScopeOptions();await selectScope('');});$('localScope').onchange=guard(async()=>{const prior=current?.id||'';try{await selectScope($('localScope').value);}catch(e){renderScopeOptions(prior);throw e;}});$('round').onchange=()=>{round=Number($('round').value);render();};$('search').oninput=()=>{cancelAnimationFrame(searchFrame);searchFrame=requestAnimationFrame(renderSearch);};$('searchMode').onchange=renderSearch;$('manualBtn').onclick=guard(manual);$('newLocal').onclick=newLocal;$('importRaw').onclick=guard(()=>beginImport('local'));$('exportLocal').onclick=guard(()=>exportExcel(false));$('exportCentral').onclick=guard(()=>exportExcel(true));$('exportPacket').onclick=guard(packetExport);$('centerLogin').onclick=connect;$('syncNow').onclick=guard(async()=>{if(!connection()?.token){connect();return;}await syncAll();});
 $('adminCompany').onchange=renderAdminLists;$('addCompany').onclick=guard(addCompany);$('addWarehouse').onclick=newLocal;$('useAdminWarehouse').onclick=guard(async()=>{const id=$('adminWarehouse').value;if(!id)throw Error('انبار را انتخاب کنید.');await selectScope(id);showTab('files');});$('showWorkerCode').onclick=guard(async()=>{$('workerCode').textContent=(await rpc('workerCode')).code;});$('importPacket').onclick=guard(packetImport);$('chooseDestination').onclick=guard(chooseDestination);
 document.body.addEventListener('click',guard(async e=>{const pick=e.target.closest('[data-pick]'),edit=e.target.closest('[data-edit]'),calc=e.target.closest('[data-calc]');if(pick)countModal(pick.dataset.pick);if(edit)editEntry(edit.dataset.edit);if(calc){const v=calc.dataset.calc,s=$('calcScreen').textContent;$('calcScreen').textContent=v==='C'?'0':v==='←'?s.slice(0,-1)||'0':v==='='?String(Math.round(arithmetic(s)*1000)/1000):s==='0'&&/\d/.test(v)?v:s+v;}}));
 nativePicker($('rawFile'),'raw');nativePicker($('packetFile'),'restore');
 try{db=await dbOpen();deviceId=await meta('deviceId');if(!deviceId){deviceId=uid();await meta('deviceId',deviceId);}conns=await meta('connections')||{};$('loginName').value=await meta('lastName')||'';$('startup').hidden=true;$('login').hidden=false;document.documentElement.dataset.appReady='true';}catch(e){$('startup').textContent='حافظهٔ دستگاه باز نشد: '+e.message+'؛ داده‌های برنامه را پاک نکنید.';}
 setInterval(()=>{if(!document.hidden)syncAll();},30000);window.addEventListener('online',()=>syncAll());document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncAll();});
}
window.addEventListener('DOMContentLoaded',init);
